import{_ as i,a0 as p,w as r,s as d,ao as l,I as s,x as o,a1 as u,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Tuxedo 已对所有用户开放基于 Ubuntu 的 TUXEDO OS | LCTT x X-CMD","titleTemplate":false,"description":"Tuxedo 已对所有用户开放基于 Ubuntu 的 TUXEDO OS | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Tuxedo 已对所有用户开放基于 Ubuntu 的 TUXEDO OS | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Tuxedo 已对所有用户开放基于 Ubuntu 的 TUXEDO OS | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220930 [Exclusive] Tuxedo Makes Ubuntu-based -TUXEDO OS- Available For All","title":"Tuxedo 已对所有用户开放基于 Ubuntu 的 TUXEDO OS","tag":"202210","desc":""},"relativePath":"202210/20220930 [Exclusive] Tuxedo Makes Ubuntu-based -TUXEDO OS- Available For All.md","filePath":"[post].md"}'),T={name:"202210/20220930 [Exclusive] Tuxedo Makes Ubuntu-based -TUXEDO OS- Available For All.md"};function a(O,t,x,U,m,D){const e=p("Link");return r(),d("div",null,[t[31]||(t[31]=l('<h1 id="tuxedo-已对所有用户开放基于-ubuntu-的-tuxedo-os" tabindex="-1">Tuxedo 已对所有用户开放基于 Ubuntu 的 TUXEDO OS <a class="header-anchor" href="#tuxedo-已对所有用户开放基于-ubuntu-的-tuxedo-os" aria-label="Permalink to “Tuxedo 已对所有用户开放基于 Ubuntu 的 TUXEDO OS”">​</a></h1><blockquote><p>TUXEDO OS 是一个基于 Ubuntu 的 Linux 发行版，旨在将 TUXEDO 在 Linux 方面的专业知识也带给非 TUXEDO 用户。</p></blockquote><p><img src="https://news.itsfoss.com/content/images/size/w1200/2022/09/tuxedo-os-1.png" alt="[独家] Tuxedo 已对所有用户开放基于 Ubuntu 的 &#39;TUXEDO OS&#39;"></p><p>又一个基于 Ubuntu 的 Linux 发行版？😕</p><p>不完全是！<strong>TUXEDO 计算机公司</strong> 是一家硬件制造商，以其专注于 Linux 的笔记本电脑和计算机而闻名。</p><p><strong>TUXEDO OS 与 Ubuntu 之间存在着一些有趣的差异</strong>。</p><p>虽然他们已经在笔记本电脑/计算机上提供预装 TUXEDO OS 的选项，但是它并未对所有人开放。</p><p>终于，他们决定将其发行版的第一个版本作为 <strong>TUXEDO OS 1</strong> 开放，该版本现已可供下载。</p><p>这也意味着你可以在自己的非 TUXEDO 系统上试用它。</p><p>所以这个思路很像 System76 的 Pop!_OS，所以这并不算一件坏事 👌</p><h3 id="搭配-kde-的-tuxedo-os-1" tabindex="-1">搭配 KDE 的 TUXEDO OS 1 <a class="header-anchor" href="#搭配-kde-的-tuxedo-os-1" aria-label="Permalink to “搭配 KDE 的 TUXEDO OS 1”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-home.jpg" alt="tuxedo 桌面"></p>',12)),s("p",null,[t[1]||(t[1]=o("TUXEDO OS 1 是基于 ",-1)),u(e,{href:"https://news.itsfoss.com/ubuntu-22-04-release/"},{default:n(()=>[...t[0]||(t[0]=[o("Ubuntu 22.04 LTS",-1)])]),_:1}),t[2]||(t[2]=o(" 的; 所以它应该可以直接在大多数设备上运行。",-1))]),s("p",null,[t[4]||(t[4]=o("与 System76 的 Pop!_OS 不同，TUXEDO OS 搭载了 ",-1)),u(e,{href:"https://news.itsfoss.com/kde-plasma-5-24-lts-release/"},{default:n(()=>[...t[3]||(t[3]=[o("KDE Plasma 5.24.6",-1)])]),_:1}),t[5]||(t[5]=o("。因此，它应当提供了一个 Windows 用户也较为熟悉的用户界面。",-1))]),t[32]||(t[32]=l('<p>但是，TUXEDO OS 还包括一些额外的功能，例如 TUXEDO 控制中心，用于微调你的硬件（CPU/风扇等），以及 TUXEDO Tomte，一个用于解决驱动程序/缺少包问题的配置服务，但是它或许能，或许不能在其他硬件配置上工作。</p><p>说到这里，让我们看看 TUXEDO OS 及其提供的功能。</p><h3 id="tuxedo-os-基于-kde-的定制化-ubuntu-体验" tabindex="-1">TUXEDO OS，基于 KDE 的定制化 Ubuntu 体验 <a class="header-anchor" href="#tuxedo-os-基于-kde-的定制化-ubuntu-体验" aria-label="Permalink to “TUXEDO OS，基于 KDE 的定制化 Ubuntu 体验”">​</a></h3><p>用户体验正如预期一样，与任何基于 KDE 的 Ubuntu 发行版相同。</p><blockquote><p>📣 我将 TUXEDO OS（预览版）用做我的主要系统来体验它。</p></blockquote><p>你会在应用和菜单上发现带有红色调的 TUXEDO 徽标。它还具有令人耳目一新的壁纸。</p><p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-menu.png" alt="tuxedo 菜单"></p><p>除了定制化的 KDE Plasma 主题，还有一些其他的变化，例如：</p><ul><li>它使用了 PipeWire 作为声音服务器，而不是 PulseAudio。</li><li>GRUB 中启用了 os-prober 功能，让用户可以方便地检测已安装的其他操作系统。</li><li>.deb 作为首选的软件包格式，而 Snap 默认情况下被禁用。</li><li>从 NetworkManagerConnectivity 检查中移除了 Canonical 的链接。</li></ul><h4 id="软件可用性" tabindex="-1">软件可用性？ <a class="header-anchor" href="#软件可用性" aria-label="Permalink to “软件可用性？”">​</a></h4><p>你可以通过 “<ruby>发现<rt>Discover</rt></ruby>” 应用来找到所有流行的软件工具，其中包括 Ubuntu 的仓库和 TUXEDO 的仓库。</p><p>它包含了 <strong>Firefox、Thunderbird、LibreOffice、VLC、Lutris 和 Heroic Games Launcher</strong> 等必备应用程序。所以我认为你不会觉得它们很臃肿。</p><p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-os-repositories.png" alt="tuxedo discover 应用"></p><p>我还注意到它默认启用了 Flatpak 集成。</p>',14)),s("p",null,[t[7]||(t[7]=o("你可以在他们的 ",-1)),u(e,{href:"https://www.tuxedocomputers.com/en/Featured-KDEs-outstanding-applications-and-tools.tuxedo"},{default:n(()=>[...t[6]||(t[6]=[o("官方网页",-1)])]),_:1}),t[8]||(t[8]=o(" 上了解有关可用软件的更多信息。",-1))]),t[33]||(t[33]=s("h4",{id:"这也给我们带来了一个重要的亮点",tabindex:"-1"},[o("这也给我们带来了一个重要的亮点 "),s("a",{class:"header-anchor",href:"#这也给我们带来了一个重要的亮点","aria-label":"Permalink to “这也给我们带来了一个重要的亮点”"},"​")],-1)),t[34]||(t[34]=s("p",null,"❌ TUXEDO OS 不会默认安装 Snap。对于 Firefox，它会像 Linux Mint 一样附带 deb 包安装。",-1)),t[35]||(t[35]=s("p",null,"✅ 值得注意的是，TUXEDO OS 22.04 LTS 附带了 Nvidia 驱动程序。",-1)),t[36]||(t[36]=s("p",null,"因此，我可以毫不费力地将它安装在带有 RTX 3060 Ti 显卡的系统上。",-1)),t[37]||(t[37]=s("h3",{id:"tuxedo-附加功能",tabindex:"-1"},[o("TUXEDO 附加功能 "),s("a",{class:"header-anchor",href:"#tuxedo-附加功能","aria-label":"Permalink to “TUXEDO 附加功能”"},"​")],-1)),t[38]||(t[38]=s("p",null,"如上所述，TUXEDO OS 附带了一些专为增强 Tuxedo 硬件的体验而量身定制的附加功能。",-1)),s("p",null,[t[10]||(t[10]=o("控制中心是监控你的系统、选择电源配置文件、控制外部水冷（",-1)),u(e,{href:"https://www.tuxedocomputers.com/en/TUXEDO-Aquaris.tuxedo"},{default:n(()=>[...t[9]||(t[9]=[o("TUXEDO Aquaris",-1)])]),_:1}),t[11]||(t[11]=o("）等的绝佳工具。",-1))]),t[39]||(t[39]=l('<p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-os-control-center.png" alt="tuxedo 控制中心"></p><p>虽然控制中心不是为非 TUXEDO 设备量身定制的，但它在大多数情况下仍然能够正常工作。</p><p>还有一个 TUXEDO WebFAI Creator 程序（定制的 BalenaEtcher）来烧录用于操作系统安装的 U 盘。</p><p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-webfai.jpg" alt="tuxedo webfai"></p><p>还有，不要忘记 TUXEDO Tomte，它无法在我的系统上运行，但可以很完美的在 TUXEDO 设备上作为配置服务运行：</p><p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-tomte.jpg" alt=""></p><h3 id="下载-tuxedo-os-1" tabindex="-1">下载 TUXEDO OS 1 <a class="header-anchor" href="#下载-tuxedo-os-1" aria-label="Permalink to “下载 TUXEDO OS 1”">​</a></h3><p>TUXEDO OS 带来了非常精致的体验。TUXEDO 背后的团队在让 Linux 运行在他们的一些最新笔记本电脑上拥有丰富的经验。因此，使用他们的 Linux 发行版，你可以对自己的体验充满信心。</p>',8)),s("p",null,[t[13]||(t[13]=o("如果你有兴趣，还可以找到关于 ",-1)),u(e,{href:"https://www.tuxedocomputers.com/en/First-Steps-with-TUXEDO-OS.tuxedo"},{default:n(()=>[...t[12]||(t[12]=[o("TUXEDO OS 入门",-1)])]),_:1}),t[14]||(t[14]=o(" 的官方文章。",-1))]),t[40]||(t[40]=s("p",null,[s("strong",null,"如果你希望获得一个基于 KDE 的定制化 Ubuntu 体验，TUXEDO OS 1 是一个不错的选择。")],-1)),t[41]||(t[41]=s("p",null,"你可以通过使用它来支持他们的计划，这可能会让你决定购买一台 TUXEDO 设备；你永远不知道以后会发生什么，对吧？",-1)),t[42]||(t[42]=s("p",null,"你可以从其官方网站下载它，并在下方的评论区中分享你的想法。",-1)),s("blockquote",null,[s("p",null,[s("strong",null,[u(e,{href:"https://www.tuxedocomputers.com/os"},{default:n(()=>[...t[15]||(t[15]=[o("下载 TUXEDO OS 1",-1)])]),_:1})])])]),t[43]||(t[43]=s("hr",null,null,-1)),s("p",null,[t[17]||(t[17]=o("via: ",-1)),u(e,{href:"https://news.itsfoss.com/tuxedo-os/"},{default:n(()=>[...t[16]||(t[16]=[o("https://news.itsfoss.com/tuxedo-os/",-1)])]),_:1})]),s("p",null,[t[22]||(t[22]=o("作者：",-1)),u(e,{href:"https://news.itsfoss.com/author/ankush/"},{default:n(()=>[...t[18]||(t[18]=[o("Ankush Das",-1)])]),_:1}),t[23]||(t[23]=o(" 选题：",-1)),u(e,{href:"https://github.com/lkxed"},{default:n(()=>[...t[19]||(t[19]=[o("lkxed",-1)])]),_:1}),t[24]||(t[24]=o(" 译者：",-1)),u(e,{href:"https://github.com/Cubik65536"},{default:n(()=>[...t[20]||(t[20]=[o("Cubik65536",-1)])]),_:1}),t[25]||(t[25]=o(" 校对：",-1)),u(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[21]||(t[21]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[28]||(t[28]=o("本文由 ",-1)),u(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[26]||(t[26]=[o("LCTT",-1)])]),_:1}),t[29]||(t[29]=o(" 原创编译，",-1)),u(e,{href:"https://linux.cn/"},{default:n(()=>[...t[27]||(t[27]=[o("Linux中国",-1)])]),_:1}),t[30]||(t[30]=o(" 荣誉推出",-1))])])}const X=i(T,[["render",a]]);export{f as __pageData,X as default};
